        "bookName": "2 Chronicles",
        "chapterNumber": 8,
        "verseNumber": 18,
        "text": "Huram sent him ships and servants who had knowledge of the sea by the hands of his servants; and they came with the servants of Solomon to Ophir, and brought from there four hundred fifty talents of gold, and brought them to king Solomon.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-8",
