        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 13,
        "verseNumber": 7,
        "text": "Worthless men were gathered to him, wicked fellows who strengthened themselves against Rehoboam the son of Solomon, when Rehoboam was young and tender hearted, and could not withstand them.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-13",
