        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 13,
        "verseNumber": 8,
        "text": "“Now you intend to withstand the kingdom of Yahweh in the hand of the sons of David. You are a great multitude, and the golden calves which Jeroboam made you for gods are with you.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-13",
