        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 17,
        "verseNumber": 7,
        "text": "Also in the third year of his reign he sent his princes, even Ben Hail, Obadiah, Zechariah, Nethanel, and Micaiah, to teach in the cities of Judah;",
