        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 18,
        "verseNumber": 31,
        "text": "When the captains of the chariots saw Jehoshaphat, they said, “It is the king of Israel!” Therefore they turned around to fight against him. But Jehoshaphat cried out, and Yahweh helped him; and God moved them to depart from him.",
        "translation": "WEB",
