        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 20,
        "verseNumber": 25,
        "text": "When Jehoshaphat and his people came to take their plunder, they found among them in abundance both riches and dead bodies, and precious jewels, which they stripped off for themselves, more than they could carry away. They took plunder for three days, it was so much.",
        "translation": "WEB",
