        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 20,
        "verseNumber": 26,
        "text": "On the fourth day, they assembled themselves in Beracah Valley, for there they blessed Yahweh. Therefore the name of that place was called “Beracah Valley” to this day.",
