        "bookName": "2 Chronicles",
        "chapterNumber": 20,
        "verseNumber": 27,
        "text": "Then they returned, every man of Judah and Jerusalem, with Jehoshaphat in front of them, to go again to Jerusalem with joy; for Yahweh had made them to rejoice over their enemies.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-20",
