        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 20,
        "verseNumber": 28,
        "text": "They came to Jerusalem with stringed instruments, harps, and trumpets to Yahweh’s house.",
        "translation": "WEB",
