        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 20,
        "verseNumber": 31,
        "text": "Jehoshaphat reigned over Judah. He was thirty-five years old when he began to reign; and he reigned twenty-five years in Jerusalem. His mother’s name was Azubah the daughter of Shilhi.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-20",
