        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 20,
        "verseNumber": 32,
        "text": "He walked in the way of Asa his father, and didn’t turn away from it, doing that which was right in Yahweh’s eyes.",
