        "chapterNumber": 20,
        "verseNumber": 34,
        "text": "Now the rest of the acts of Jehoshaphat, first and last, behold, they are written in the history of Jehu the son of Hanani, which is included in the book of the kings of Israel.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-20",
