        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 21,
        "verseNumber": 19,
        "text": "In process of time, at the end of two years, his bowels fell out by reason of his sickness, and he died of severe diseases. His people made no burning for him, like the burning of his fathers.",
        "translation": "WEB",
