        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 22,
        "verseNumber": 11,
        "text": "But Jehoshabeath, the king’s daughter, took Joash the son of Ahaziah, and stealthily rescued him from among the king’s sons who were slain, and put him and his nurse in the bedroom. So Jehoshabeath, the daughter of king Jehoram, the wife of Jehoiada the priest (for she was the sister of Ahaziah), hid him from Athaliah, so that she didn’t kill him.",
        "translation": "WEB",
