        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 25,
        "verseNumber": 11,
        "text": "Amaziah took courage, and led his people out, and went to the Valley of Salt, and struck ten thousand of the children of Seir.",
