        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 25,
        "verseNumber": 15,
        "text": "Therefore Yahweh’s anger burned against Amaziah, and he sent to him a prophet, who said to him, “Why have you sought after the gods of the people, which have not delivered their own people out of your hand?”",
        "translation": "WEB",
        "illustrationId": "ill-2ch-25",
