        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 25,
        "verseNumber": 16,
        "text": "As he talked with him, the king said to him, “Have we made you one of the king’s counselors? Stop! Why should you be struck down?” Then the prophet stopped, and said, “I know that God has determined to destroy you, because you have done this, and have not listened to my counsel.”",
        "translation": "WEB",
        "illustrationId": "ill-2ch-25",
        "linkedEntities": []
