        "chapterNumber": 26,
        "verseNumber": 6,
        "text": "He went out and fought against the Philistines, and broke down the wall of Gath, the wall of Jabneh, and the wall of Ashdod; and he built cities in the country of Ashdod, and among the Philistines.",
        "translation": "WEB",
