        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 26,
        "verseNumber": 9,
        "text": "Moreover Uzziah built towers in Jerusalem at the corner gate, at the valley gate, and at the turning of the wall, and fortified them.",
