        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 26,
        "verseNumber": 21,
        "text": "Uzziah the king was a leper to the day of his death, and lived in a separate house, being a leper; for he was cut off from Yahweh’s house. Jotham his son was over the king’s house, judging the people of the land.",
        "translation": "WEB",
