        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 31,
        "verseNumber": 13,
        "text": "Jehiel, Azaziah, Nahath, Asahel, Jerimoth, Jozabad, Eliel, Ismachiah, Mahath, and Benaiah were overseers under the hand of Conaniah and Shimei his brother, by the appointment of Hezekiah the king and Azariah the ruler of God’s house.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-31",
