        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 31,
        "verseNumber": 14,
        "text": "Kore the son of Imnah the Levite, the gatekeeper at the east gate, was over the free will offerings of God, to distribute Yahweh’s offerings and the most holy things.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-31",
