        "bookName": "2 Chronicles",
        "chapterNumber": 34,
        "verseNumber": 7,
        "text": "He broke down the altars, and beat the Asherah poles and the engraved images into powder, and cut down all the incense altars throughout all the land of Israel, then returned to Jerusalem.",
