        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 34,
        "verseNumber": 22,
        "text": "So Hilkiah, and they whom the king had commanded, went to Huldah the prophetess, the wife of Shallum the son of Tokhath, the son of Hasrah, keeper of the wardrobe (now she lived in Jerusalem in the second quarter), and they spoke to her to that effect.",
        "translation": "WEB",
