        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 34,
        "verseNumber": 24,
        "text": "“Yahweh says, ‘Behold, I will bring evil on this place, and on its inhabitants, even all the curses that are written in the book which they have read before the king of Judah.",
        "translation": "WEB",
        "illustrationId": "ill-2ch-34",
