        "chapterNumber": 34,
        "verseNumber": 26,
        "text": "But to the king of Judah, who sent you to inquire of Yahweh, you shall tell him this, ‘Yahweh, the God of Israel says: “About the words which you have heard,",
        "translation": "WEB",
        "illustrationId": "ill-2ch-34",
