        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 35,
        "verseNumber": 9,
        "text": "Conaniah also, and Shemaiah and Nethanel, his brothers, and Hashabiah, Jeiel, and Jozabad, the chiefs of the Levites, gave to the Levites for the Passover offerings five thousand small livestock and five hundred head of cattle.",
        "translation": "WEB",
