        "bookId": "2CH",
        "bookName": "2 Chronicles",
        "chapterNumber": 35,
        "verseNumber": 20,
        "text": "After all this, when Josiah had prepared the temple, Neco king of Egypt went up to fight against Carchemish by the Euphrates, and Josiah went out against him.",
